package com.pointverse.app;
import android.content.Context;import android.graphics.*;import android.view.*;
final class CropCanvas extends View{
    private final Bitmap source;private final Paint paint=new Paint(3);private final ScaleGestureDetector scale;
    private float zoom=1,dx=0,dy=0,lastX,lastY;private float side,left,top;
    CropCanvas(Context context,Bitmap image){super(context);source=image;setMinimumHeight(800);scale=new ScaleGestureDetector(context,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(1,Math.min(6,zoom*d.getScaleFactor()));clamp();invalidate();return true;}});}
    protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(Color.BLACK);side=Math.min(getWidth(),getHeight())*.92f;left=(getWidth()-side)/2;top=(getHeight()-side)/2;clamp();float base=side/Math.min(source.getWidth(),source.getHeight())*zoom;canvas.save();canvas.clipRect(left,top,left+side,top+side);canvas.translate(getWidth()/2f+dx,getHeight()/2f+dy);canvas.scale(base,base);canvas.drawBitmap(source,-source.getWidth()/2f,-source.getHeight()/2f,paint);canvas.restore();paint.setStyle(Paint.Style.STROKE);paint.setColor(Color.WHITE);paint.setStrokeWidth(2);canvas.drawRect(left,top,left+side,top+side,paint);paint.setStyle(Paint.Style.FILL);}
    private void clamp(){float factor=side/Math.min(source.getWidth(),source.getHeight())*zoom;float mx=Math.max(0,(source.getWidth()*factor-side)/2),my=Math.max(0,(source.getHeight()*factor-side)/2);dx=Math.max(-mx,Math.min(mx,dx));dy=Math.max(-my,Math.min(my,dy));}
    public boolean onTouchEvent(android.view.MotionEvent event){scale.onTouchEvent(event);if(event.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=event.getX();lastY=event.getY();}else if(event.getActionMasked()==MotionEvent.ACTION_MOVE){if(!scale.isInProgress()){dx+=event.getX()-lastX;dy+=event.getY()-lastY;clamp();invalidate();}lastX=event.getX();lastY=event.getY();}return true;}
    Bitmap result(){int edge=1024;Bitmap result=Bitmap.createBitmap(edge,edge,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);float ratio=edge/side,base=side/Math.min(source.getWidth(),source.getHeight())*zoom;canvas.translate(edge/2f+dx*ratio,edge/2f+dy*ratio);canvas.scale(base*ratio,base*ratio);canvas.drawBitmap(source,-source.getWidth()/2f,-source.getHeight()/2f,paint);return result;}
}
